/**
 * Central asset manifest. Real art is described in public/assets/manifest.json (generated by
 * tools/extract_assets.py). If that file or any image is missing, the game falls back to
 * procedurally drawn placeholders, so nothing here is required for the game to run.
 */
export type Dir = 'down' | 'left' | 'right' | 'up';

export interface SpriteRef {
  file: string;
  w: number;
  h: number;
  /** origin inside the sprite (0..1); default bottom-center (0.5, 1) */
  ox?: number;
  oy?: number;
  /** extra render scale multiplier */
  scale?: number;
}

export interface Manifest {
  version: number;
  /** source pixels per logical 32px tile (art is normalised to this) */
  pxPerTile: number;
  terrain?: {
    grass?: SpriteRef[];
    flowerGrass?: SpriteRef[];
    water?: SpriteRef[];
    /** keyed by neighbour mask "NESW" of 0/1, e.g. "0101" = straight east-west road */
    dirt?: Record<string, SpriteRef>;
    stone?: Record<string, SpriteRef>;
  };
  buildings?: Record<string, Record<string, SpriteRef>>;
  decorations?: Record<string, SpriteRef>;
  players?: Record<string, Partial<Record<Dir, SpriteRef[]>>>;
  npcs?: Record<string, Partial<Record<Dir, SpriteRef[]>>>;
  portraits?: Record<string, SpriteRef>;
  /** character-select / HUD portraits of the six playable characters (c1..c6) */
  playerPortraits?: Record<string, SpriteRef>;
  ui?: Record<string, SpriteRef>;
  title?: SpriteRef;
  /** packed runtime atlases (frame name == texture key); preferred over the individual files */
  atlases?: { key: string; image: string; data: string }[];
  /** file -> short content hash, appended as ?v= so cached old files are never mixed with new ones */
  versions?: Record<string, string>;
}

/** How a building level is drawn. footprint is what it occupies on the grid, independent of the image size. */
export interface BuildingVisual {
  buildingId: string;
  level: 1 | 2 | 3;
  textureKey: string;
  footprintWidth: number;
  footprintHeight: number;
  originX: number;
  originY: number;
  renderScale: number;
}

export function getBuildingVisual(m: Manifest | null, buildingId: string, level: number, footprint: { w: number; h: number }): BuildingVisual {
  const lv = (Math.min(3, Math.max(1, level)) as 1 | 2 | 3);
  const ref = m?.buildings?.[buildingId]?.[String(lv)] ?? m?.buildings?.[buildingId]?.['1'];
  return {
    buildingId, level: lv, textureKey: bKey(buildingId, ref && m?.buildings?.[buildingId]?.[String(lv)] ? lv : 1),
    footprintWidth: footprint.w, footprintHeight: footprint.h,
    originX: ref?.ox ?? 0.5, originY: ref?.oy ?? 1, renderScale: ref?.scale ?? 1,
  };
}

export const MANIFEST_URL = 'assets/manifest.json';
export const DEFAULT_PX_PER_TILE = 64;

export const bKey = (id: string, level: number) => `b:${id}:${level}`;
export const dKey = (id: string) => `d:${id}`;
export const pKey = (kind: 'p' | 'n', id: string, dir: Dir, i: number) => `${kind}:${id}:${dir}:${i}`;
export const tKey = (name: string, i = 0) => `t:${name}:${i}`;

let versions: Record<string, string> = {};

export function assetUrl(file: string): string {
  const f = file.replace(/^\/+/, '');
  const v = versions[f];
  return 'assets/' + f + (v ? `?v=${v}` : '');
}

export async function fetchManifest(): Promise<Manifest | null> {
  try {
    const r = await fetch(MANIFEST_URL, { cache: 'no-cache' });
    if (!r.ok) return null;
    const m = (await r.json()) as Manifest;
    if (m && typeof m === 'object') versions = m.versions ?? {};
    return m && typeof m === 'object' ? m : null;
  } catch {
    return null;
  }
}

/** Flat list of every image the manifest wants loaded: [textureKey, file]. */
export function listImages(m: Manifest): [string, string][] {
  const out: [string, string][] = [];
  const t = m.terrain ?? {};
  (t.grass ?? []).forEach((r, i) => out.push([tKey('grass', i), r.file]));
  (t.flowerGrass ?? []).forEach((r, i) => out.push([tKey('flower', i), r.file]));
  (t.water ?? []).forEach((r, i) => out.push([tKey('water', i), r.file]));
  Object.entries(t.dirt ?? {}).forEach(([k, r]) => out.push([`t:dirt:${k}`, r.file]));
  Object.entries(t.stone ?? {}).forEach(([k, r]) => out.push([`t:stone:${k}`, r.file]));
  for (const [id, lv] of Object.entries(m.buildings ?? {})) for (const [l, r] of Object.entries(lv)) out.push([bKey(id, Number(l)), r.file]);
  for (const [id, r] of Object.entries(m.decorations ?? {})) out.push([dKey(id), r.file]);
  for (const [kind, group] of [['p', m.players], ['n', m.npcs]] as const) {
    for (const [id, dirs] of Object.entries(group ?? {})) {
      for (const [dir, refs] of Object.entries(dirs)) (refs ?? []).forEach((r, i) => out.push([pKey(kind, id, dir as Dir, i), r.file]));
    }
  }
  return out;
}
